package com.heluo.museum.appointment;
import com.heluo.museum.common.api.ApiResponse;import jakarta.transaction.Transactional;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/appointments") public class AppointmentController {private final JdbcTemplate jdbc;AppointmentController(JdbcTemplate jdbc){this.jdbc=jdbc;}@PostMapping @Transactional public ApiResponse<Map<String,Object>> create(Authentication a,@Valid @RequestBody Create b){long uid=(Long)a.getPrincipal();int changed=jdbc.update("update appointment_slots set reserved_people=reserved_people+? where id=? and status='OPEN' and reserved_people+?<=capacity",b.visitorCount(),b.slotId(),b.visitorCount());if(changed!=1)throw new IllegalArgumentException("预约时段不可用或名额不足");String no="AP"+UUID.randomUUID().toString().replace("-","").substring(0,16).toUpperCase();jdbc.update("insert into appointments(appointment_no,user_id,slot_id,visitor_count,contact_name,contact_phone,contact_email,notes) values(?,?,?,?,?,?,?,?)",no,uid,b.slotId(),b.visitorCount(),b.contactName(),b.contactPhone(),b.contactEmail(),b.notes());return ApiResponse.ok(Map.of("appointmentNo",no,"status","PENDING"),"appointment");}public record Create(@NotNull Long slotId,@Min(1) @Max(30) int visitorCount,@NotBlank @Size(max=50) String contactName,@NotBlank @Size(max=20) String contactPhone,@Email @NotBlank String contactEmail,@Size(max=500) String notes){}}
